# Generated by manage.py generate_test_cases.
from django.http import HttpResponse
from django.utils import timezone

from bloomerp.models.communication.instant_messaging import (
    IMConversation,
    IMConversationParticipant,
    IMMessage,
    IMMessageReaction,
)
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestReactionComponent(BloomerpComponentTestCase):
    """Verify idempotent reaction changes and their private conversation boundary."""

    view_name = "components_im_reaction"

    def prepare_message(self, scenario: RequestScenario) -> None:
        """Create a message with two members and another participant's reaction."""
        self.chat = IMConversation.objects.create(kind="group")
        self.member = IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.normal_user
        )
        other = IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.admin_user
        )
        self.message = IMMessage.objects.create(
            conversation=self.chat, sender=other, sequence=1, body="React to this"
        )
        IMMessageReaction.objects.create(
            message=self.message, participant=other, emoji="👍"
        )
        scenario.view_kwargs = {
            "conversation_id": self.chat.pk,
            "message_id": self.message.pk,
        }
        scenario.data = {"emoji": "👍", "active": "true"}

    def prepare_existing(self, scenario: RequestScenario) -> None:
        """Create the caller's reaction before a duplicate add request."""
        self.prepare_message(scenario)
        IMMessageReaction.objects.create(
            message=self.message, participant=self.member, emoji="👍"
        )

    def prepare_remove(self, scenario: RequestScenario) -> None:
        """Remove only the current user's reaction while retaining the other vote."""
        self.prepare_existing(scenario)
        scenario.data["active"] = "false"

    def prepare_remove_again(self, scenario: RequestScenario) -> None:
        """Retry removal after the caller's reaction has already disappeared."""
        self.prepare_message(scenario)
        scenario.data["active"] = "false"

    def prepare_left(self, scenario: RequestScenario) -> None:
        """Revoke membership before changing a message reaction."""
        self.prepare_message(scenario)
        self.member.left_at = timezone.now()
        self.member.save()

    def prepare_foreign(self, scenario: RequestScenario) -> None:
        """Pair an accessible conversation with another conversation's message."""
        self.prepare_message(scenario)
        chat = IMConversation.objects.create(kind="group")
        member = IMConversationParticipant.objects.create(
            conversation=chat, user=self.admin_user
        )
        message = IMMessage.objects.create(
            conversation=chat, sender=member, sequence=1, body="Private"
        )
        scenario.view_kwargs["message_id"] = message.pk

    def prepare_deleted(self, scenario: RequestScenario) -> None:
        """Reject reaction changes after a message is deleted."""
        self.prepare_message(scenario)
        self.message.deleted_at = timezone.now()
        self.message.save()

    def prepare_archived(self, scenario: RequestScenario) -> None:
        """Reject reaction changes on archived conversations."""
        self.prepare_message(scenario)
        self.chat.status = "archived"
        self.chat.save()

    def prepare_invalid(self, scenario: RequestScenario) -> None:
        """Reject arbitrary text in place of a supported picker emoji."""
        self.prepare_message(scenario)
        scenario.data["emoji"] = "<script>invalid</script>"

    def has_two_reactions(self, response: HttpResponse) -> bool:
        """Ensure duplicate adds leave exactly one vote per participant."""
        return (
            self.message.reactions.count() == 2
            and self.message.reactions.filter(
                participant=self.member, emoji="👍"
            ).count()
            == 1
        )

    def only_other_reaction(self, response: HttpResponse) -> bool:
        """Ensure the request never removes another participant's reaction."""
        return (
            self.message.reactions.count() == 1
            and not self.message.reactions.filter(participant=self.member).exists()
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover create, retry, removal, method restrictions and authorization."""
        return [
            RequestScenario(
                name="Add reaction",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_message,
                expected=ExpectedResult(response_validators=[self.has_two_reactions]),
            ),
            RequestScenario(
                name="Add retry is idempotent",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_existing,
                expected=ExpectedResult(response_validators=[self.has_two_reactions]),
            ),
            RequestScenario(
                name="Remove own reaction",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_remove,
                expected=ExpectedResult(response_validators=[self.only_other_reaction]),
            ),
            RequestScenario(
                name="Removal retry is idempotent",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_remove_again,
                expected=ExpectedResult(response_validators=[self.only_other_reaction]),
            ),
            RequestScenario(
                name="Former member denied",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_left,
                expected=ExpectedResult(
                    status_code=403, response_validators=[self.only_other_reaction]
                ),
            ),
            RequestScenario(
                name="Foreign message rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_foreign,
                expected=ExpectedResult(
                    status_code=400, response_validators=[self.only_other_reaction]
                ),
            ),
            RequestScenario(
                name="Deleted message rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_deleted,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Archived chat rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_archived,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Invalid emoji rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_invalid,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Anonymous denied",
                method="POST",
                prepare=self.prepare_message,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="GET cannot mutate",
                user=self.normal_user,
                prepare=self.prepare_message,
                expected=ExpectedResult(status_code=405),
            ),
        ]
